namespace EnterpriseDocumentIntelligence.AgentService.Domain; public enum AgentTurnRole{User,Assistant,Tool} public sealed record AgentTurn(AgentTurnRole Role,string Content,string? ToolName=null){public AgentTurn{if(string.IsNullOrWhiteSpace(Content))throw new ArgumentException("Content is required.");}} public sealed class AgentConversation(Guid id,string tenantId){private readonly List<AgentTurn> _turns=[];public Guid Id{get;}=id;public string TenantId{get;}=string.IsNullOrWhiteSpace(tenantId)?throw new ArgumentException("Tenant is required."):tenantId;public IReadOnlyList<AgentTurn> Turns=>_turns;public void Add(AgentTurn turn)=>_turns.Add(turn);}